/*
 * "Atribuir tópico": busca o usuário pelo nome e grava o responsável
 * (`canelaAssignee`) no tópico. Com alguém atribuído, também dá para remover.
 */
import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import Avatar from 'flarum/common/components/Avatar';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import username from 'flarum/common/helpers/username';
import Stream from 'flarum/common/utils/Stream';
import { debounce } from 'flarum/common/utils/throttleDebounce';
import { t } from '../../utils/settings';
export default class AssignModal extends Modal {
  query = Stream('');
  results = [];
  searching = false;
  saving = false;
  className() {
    return 'CanelaAssignModal Modal--small';
  }
  title() {
    return t('assign.title');
  }
  content() {
    const current = this.attrs.discussion.canelaAssignee?.() || null;
    return m("div", {
      className: "Modal-body"
    }, m("div", {
      className: "Form-group"
    }, m("input", {
      className: "FormControl",
      type: "search",
      placeholder: t('assign.placeholder'),
      value: this.query(),
      oninput: event => {
        this.query(event.target.value);
        this.search();
      },
      oncreate: vnode => vnode.dom.focus()
    })), m("ul", {
      className: "CanelaAssignModal-results"
    }, this.searching ? m(LoadingIndicator, {
      size: "small"
    }) : null, this.results.map(user => m("li", null, m("button", {
      type: "button",
      className: "CanelaAssignModal-user",
      disabled: this.saving,
      onclick: () => this.assign(user)
    }, m(Avatar, {
      user: user
    }), m("span", {
      className: "CanelaAssignModal-name"
    }, username(user)), m("span", {
      className: "CanelaAssignModal-handle"
    }, "@", user.username()))))), current ? m(Button, {
      className: "Button Button--block CanelaAssignModal-remove",
      icon: "fas fa-user-xmark",
      disabled: this.saving,
      onclick: () => this.assign(null)
    }, t('assign.remove', {
      username: username(current)
    })) : null);
  }
  search = debounce(250, () => {
    const q = this.query().trim();
    if (q.length < 2) {
      this.results = [];
      m.redraw();
      return;
    }
    this.searching = true;
    m.redraw();
    app.store.find('users', {
      filter: {
        q
      },
      page: {
        limit: 6
      }
    }).then(users => this.results = [...users]).catch(() => this.results = []).finally(() => {
      this.searching = false;
      m.redraw();
    });
  });
  assign(user) {
    this.saving = true;
    this.attrs.discussion.save({
      relationships: {
        canelaAssignee: user
      }
    }).then(() => this.hide()).catch(() => {}).finally(() => {
      this.saving = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ramon-canela', 'forum/features/assign/AssignModal', AssignModal);